#include "prior/world_cut_geometry.hpp"
#include "fixture.hpp"
int main(int argc,char**argv){Input input;input.original=std::make_shared<const Mesh>(fixture());input.terrainObjects={0};input.active=true;Cut cut;cut.normal={1,0,0};cut.field=1;input.cuts={cut};Projection old;const char*failure=nullptr;if(!prepare(input,old,&failure)){std::cerr<<failure<<"\n";return 2;}assert(!same(old.outer.at(0),input.original->at(0)));assert(area(old.outer.at(1))<area(input.original->at(1)));std::ofstream(argv[1])<<old.checkpoint;std::cout<<"legacy terrain outer="<<old.outer.at(0).size()<<" stone="<<old.outer.at(1).size()<<" changed="<<old.material->changed.size()<<" caps="<<old.rawCaps.size()<<"\n";for(auto&p:old.rawCaps)std::cout<<"cap object="<<p.object<<" area="<<area(p.surface.at(p.object))<<" boundsY="<<storm_ship_laser::bounds(p.surface).lo.y<<","<<storm_ship_laser::bounds(p.surface).hi.y<<"\n";}
